begin;
do $$ declare t record;n bigint; begin
 if (select count(*) from public.companies where id='86100000-0000-4000-8000-0000000000a1' and code='P6C-S16-CONCURRENCY')<>1 then raise exception 'Company mismatch'; end if;
 if (select count(*) from public.subcontracts where company_id='86100000-0000-4000-8000-0000000000a1')<>1 or not exists(select 1 from public.subcontracts where id='86100000-0000-4000-8000-0000000000d1' and contract_number='0001' and original_contract_value_minor=1 and retention_bps=0 and status='ACTIVE') then raise exception 'Subcontract mismatch'; end if;
 for t in select table_name from information_schema.columns where table_schema='public' and column_name='company_id' and table_name not in ('company_settings','company_memberships','projects','parties','subcontracts') loop execute format('select count(*) from public.%I where company_id=$1',t.table_name) into n using '86100000-0000-4000-8000-0000000000a1'::uuid; if n<>0 then raise exception 'Unexpected dependency %',t.table_name; end if; end loop;
end $$;
delete from public.subcontracts where company_id='86100000-0000-4000-8000-0000000000a1'; delete from public.projects where company_id='86100000-0000-4000-8000-0000000000a1'; delete from public.parties where company_id='86100000-0000-4000-8000-0000000000a1'; delete from public.company_memberships where company_id='86100000-0000-4000-8000-0000000000a1'; delete from public.company_settings where company_id='86100000-0000-4000-8000-0000000000a1'; delete from public.companies where id='86100000-0000-4000-8000-0000000000a1'; commit;
